  async function renderDocumentHistory(documentId,body){body.innerHTML='<div class="v5100-empty">Загружаем историю…</div>';try{var rows=await api('/api/v51/center?history=true');rows=rows.filter(function(row){return row.document&&Number(row.document.id)===Number(documentId);});body.innerHTML='<div class="v5100-toolbar"><input data-v5100-history-search placeholder="Поиск сотрудника"><select data-v5100-history-status><option value="">Все статусы</option><option value="completed">Ознакомлен</option><option value="overdue">Просрочено</option><option value="not_started">Не приступил</option></select><select data-v5100-history-group><option value="edition">Группировать по редакции</option><option value="employee">По сотруднику</option><option value="none">Без группировки</option></select></div><div data-v5100-history-rows></div>';function draw(){var q=body.querySelector('[data-v5100-history-search]').value.toLowerCase(),s=body.querySelector('[data-v5100-history-status]').value,filtered=rows.filter(function(row){return(!q||row.userName.toLowerCase().includes(q))&&(!s||row.status===s);});body.querySelector('[data-v5100-history-rows]').innerHTML='<div class="table-card"><table class="admin-table"><thead><tr><th>Сотрудник</th><th>Редакция</th><th>Статус</th><th>Срок</th><th>Завершено</th></tr></thead><tbody>'+(filtered.map(function(row){return '<tr><td>'+h(row.userName)+'</td><td>'+h(editionTitle(row.edition))+'</td><td><span class="v5100-badge '+statusClass(row.status)+'">'+h(statusLabel(row.status))+'</span></td><td>'+fmtDate(row.dueAt)+'</td><td>'+fmtDate(row.completedAt)+'</td></tr>';}).join('')||'<tr><td colspan="5">История пока пуста</td></tr>')+'</tbody></table></div>';}body.querySelectorAll('input,select').forEach(function(x){x.oninput=draw;x.onchange=draw;});draw();}catch(error){body.innerHTML='<div class="v5100-empty">'+h(error.message||error)+'</div>';}}

